import { WaterSurfaceModel } from './WaterSurfaceModel';
import type { WaterCell } from '../types';

/** One World's water masks: authored cells, the presentation world size and the chunk origins to bake. */
export interface WaterMaskJob {
  readonly cells: readonly WaterCell[];
  readonly width: number;
  readonly height: number;
  readonly chunkSize: number;
  readonly origins: readonly { readonly x: number; readonly y: number }[];
}

/** Chunk key of a mask, as the renderer keeps its masks. */
export function waterMaskKey(x: number, y: number, chunkSize: number): string {
  return `${x / chunkSize},${y / chunkSize}`;
}

/** The job of a World's water: every chunk the water reaches. The lobby prebake builds the same one. */
export function createWaterMaskJob(cells: readonly WaterCell[], width: number, height: number, chunkSize: number): WaterMaskJob {
  const origins = new WaterSurfaceModel(cells, { width, height }).getChunkOrigins(chunkSize, width, height);
  return { cells: cells.map(({ gridX, gridY }) => ({ gridX, gridY })), width, height, chunkSize, origins };
}

/** One baked chunk; `data` is the RGBA mask (`WaterMask.data`) as a transferable buffer. */
export interface WaterMaskJobResult {
  readonly x: number;
  readonly y: number;
  readonly size: number;
  readonly data: ArrayBuffer;
  readonly cpuMs: number;
}

/**
 * Bakes the masks in request order with exactly the arithmetic of `WaterSurfaceModel.bake`, which the
 * main-thread fallback runs too. Water is authored, so the masks depend on the layout only, never on
 * the deployment seed (Steam plan L11).
 */
export function bakeWaterMaskChunks(job: WaterMaskJob, publish: (result: WaterMaskJobResult) => void): void {
  const model = new WaterSurfaceModel(job.cells, { width: job.width, height: job.height });
  for (const { x, y } of job.origins) {
    const started = performance.now();
    const mask = model.bake(x, y, job.chunkSize);
    publish({ x, y, size: mask.size, data: mask.data.buffer as ArrayBuffer, cpuMs: performance.now() - started });
  }
}
