import { bakeWaterMaskChunks, type WaterMaskJob } from './WaterMaskJob';

// One job per World: every chunk is posted as soon as it is baked, its buffer transferred.
self.onmessage = (event: MessageEvent<WaterMaskJob>): void => {
  bakeWaterMaskChunks(event.data, result => self.postMessage(result, { transfer: [result.data] }));
};
